import React, { useState } from 'react';

function Dashboard() {
  const [tasks, setTasks] = useState([]);
  const [title, setTitle] = useState('');

  const addTask = () => {
    if (!title) return;

    const newTask = {
      id: Date.now(),
      title
    };

    setTasks([...tasks, newTask]);
    setTitle('');
  };

  const deleteTask = (id) => {
    setTasks(tasks.filter(task => task.id !== id));
  };

  return (
    <div
      style={{
        minHeight: '100vh',
        background: '#f8fafc',
        padding: '30px'
      }}
    >
      <h1 style={{ color: '#1e293b' }}>
        Task Dashboard
      </h1>

      <div style={{ marginTop: '20px' }}>
        <input
          type="text"
          placeholder="Enter task"
          value={title}
          onChange={(e) => setTitle(e.target.value)}
          style={{
            padding: '12px',
            width: '300px',
            borderRadius: '8px',
            border: '1px solid #cbd5e1'
          }}
        />

        <button
          onClick={addTask}
          style={{
            padding: '12px 20px',
            marginLeft: '10px',
            background: '#4f46e5',
            color: 'white',
            border: 'none',
            borderRadius: '8px',
            cursor: 'pointer'
          }}
        >
          Add Task
        </button>
      </div>

      <div style={{ marginTop: '30px' }}>
        {tasks.map((task) => (
          <div
            key={task.id}
            style={{
              background: 'white',
              padding: '20px',
              borderRadius: '10px',
              marginBottom: '15px',
              boxShadow: '0 2px 10px rgba(0,0,0,0.08)',
              display: 'flex',
              justifyContent: 'space-between',
              alignItems: 'center'
            }}
          >
            <h3>{task.title}</h3>

            <button
              onClick={() => deleteTask(task.id)}
              style={{
                background: '#ef4444',
                color: 'white',
                border: 'none',
                padding: '10px 15px',
                borderRadius: '6px',
                cursor: 'pointer'
              }}
            >
              Delete
            </button>
          </div>
        ))}
      </div>
    </div>
  );
}

export default Dashboard;
